# Rule-based vs learning-based: sorting toy coins A, B, C by weight (made-up grams)
# Rule-based: the developer writes the rules
def rule_based(weight):
    if weight < 4.5:
        return "A"
    elif weight < 5.5:
        return "B"
    else:
        return "C"

# Learning-based: the program learns an average weight for each label
training_data = [(3.8, "A"), (3.9, "A"), (4.9, "B"),
                 (4.8, "B"), (6.0, "C"), (6.1, "C")]
averages = {}
for label in ["A", "B", "C"]:
    w = [x for x, y in training_data if y == label]
    averages[label] = round(sum(w) / len(w), 2)
print("Learnt averages:", averages)

def learnt(weight):
    best = None
    for label, avg in averages.items():
        if best is None or abs(weight - avg) < abs(weight - averages[best]):
            best = label
    return best

for coin in [3.85, 5.0, 6.05]:
    print(coin, "g -> rule:", rule_based(coin), "| learnt:", learnt(coin))

